import oop_bg13_glow_f0_v2 from '../../assets/opening/v2/op-bg13-glow-f0-v2.png';
import oop_bg13_glow_f1_v2 from '../../assets/opening/v2/op-bg13-glow-f1-v2.png';
import oop_ch04_sit_f0_v2 from '../../assets/opening/v2/op-ch04-sit-f0-v2.png';

export const OPENING_ASSET_URLS: Record<string, string> = {
  'op-bg03-harbor-sky-night': oop_bg03_harbor_sky_night_v2,
  'op-bg03-harbor-mid-night': oop_bg03_harbor_mid_night_v2,
  'op-bg03-harbor-breakwater-night': oop_bg03_harbor_breakwater_night_v2,
  'op-bg03-harbor-near-night': oop_bg03_harbor_near_night_v2,
  'op-sp01-ship-dark': oop_sp01_ship_dark_v2,
  'op-sp01-ship-flash': oop_sp01_ship_flash_v2,
  'op-bg05-hatch-dark': oop_bg05_hatch_dark_v2,
  'op-bg05-hatch-lit': oop_bg05_hatch_lit_v2,
  'op-ch03-near-f0': oop_ch03_near_f0_v2,
  'op-ch03-near-f1': oop_ch03_near_f1_v2,
  'op-bg13-roof-sky': oop_bg13_roof_sky_v2,
  'op-bg13-roof-mid': oop_bg13_roof_mid_v2,
  'op-bg13-roof-near': oop_bg13_roof_near_v2,
  'op-bg13-glow-f0': oop_bg13_glow_f0_v2,
  'op-bg13-glow-f1': oop_bg13_glow_f1_v2,
  'op-ch04-sit-f0': oop_ch04_sit_f0_v2,
};
/** Size, placement on another layer (top-left, art pixels) and foot anchor, from the manifest. */
export const OPENING_ASSET_META: Record<string, { w: number; h: number; place: { layer: string; xy: [number, number] } | null; anchor: [number, number] | null }> = {
  'op-bg03-harbor-sky-night': { w: 960, h: 360, place: null, anchor: null },
  'op-bg03-harbor-mid-night': { w: 960, h: 360, place: null, anchor: null },
  'op-bg03-harbor-breakwater-night': { w: 960, h: 360, place: null, anchor: null },
  'op-bg03-harbor-near-night': { w: 960, h: 360, place: null, anchor: null },
  'op-sp01-ship-dark': { w: 400, h: 160, place: null, anchor: null },
  'op-sp01-ship-flash': { w: 400, h: 160, place: null, anchor: null },
  'op-bg05-hatch-dark': { w: 640, h: 360, place: null, anchor: null },
  'op-bg05-hatch-lit': { w: 640, h: 360, place: null, anchor: null },
  'op-ch03-near-f0': { w: 160, h: 280, place: { layer: 'op-bg05-hatch-lit', xy: [272, 4] }, anchor: [80, 360] },
  'op-ch03-near-f1': { w: 160, h: 280, place: { layer: 'op-bg05-hatch-lit', xy: [272, 4] }, anchor: [80, 360] },
  'op-bg13-roof-sky': { w: 960, h: 360, place: null, anchor: null },
  'op-bg13-roof-mid': { w: 960, h: 360, place: null, anchor: null },
  'op-bg13-roof-near': { w: 960, h: 360, place: null, anchor: null },
  'op-bg13-glow-f0': { w: 64, h: 48, place: { layer: 'op-bg13-roof-sky', xy: [869, 202] }, anchor: null },
  'op-bg13-glow-f1': { w: 64, h: 48, place: { layer: 'op-bg13-roof-sky', xy: [869, 202] }, anchor: null },
  'op-ch04-sit-f0': { w: 64, h: 76, place: { layer: 'op-bg13-roof-near', xy: [215, 108] }, anchor: [49, 71] },
};

export type OpeningArt = Record<string, HTMLImageElement>;

/** Decode every plate; null when any fails, and the animatic keeps its placeholder painters. */
export async function loadOpeningArt(): Promise<OpeningArt | null> {
  try {
    const entries = await Promise.all(Object.entries(OPENING_ASSET_URLS).map(async ([id, src]) => {
      const image = new Image(); image.src = src; await image.decode(); return [id, image] as const;
    }));
    return Object.fromEntries(entries);
  } catch (error) {
    console.error('Opening art failed to decode; showing the placeholder frames.', error);
    return null;
  }
}
